import { Effect, Schema } from "effect";
import { DecisionClient, Service } from "./decision-client.js";
import { Media } from "./media.js";
import { tryRequest } from "./media-model.js";
import { AIError, HttpOptions, ModelID, ProviderID, ProviderMetadata, ProviderOptions, } from "./schema/index.js";
// ---------------------------------------------------------------------------
// Input
// ---------------------------------------------------------------------------
export const DecisionTextPart = Schema.Struct({ type: Schema.Literal("text"), text: Schema.String });
export const DecisionJsonPart = Schema.Struct({ type: Schema.Literal("json"), value: Schema.Json });
export const DecisionMediaPart = Schema.Struct({
    type: Schema.Literal("media"),
    media: Media.AssetSchema,
    filename: Schema.optional(Schema.String),
});
export const DecisionPart = Schema.Union([DecisionTextPart, DecisionJsonPart, DecisionMediaPart]).pipe(Schema.toTaggedUnion("type"));
// ---------------------------------------------------------------------------
// Questions
// ---------------------------------------------------------------------------
/** Choice values are typed: `true` and `"true"` are different values. */
export const ChoiceValue = Schema.Union([Schema.String, Schema.Boolean]);
export const PredicateQuestion = Schema.Struct({
    name: Schema.String,
    type: Schema.Literal("predicate"),
    instructions: Schema.String,
});
export const ChoiceQuestion = Schema.Struct({
    name: Schema.String,
    type: Schema.Literal("choice"),
    instructions: Schema.String,
    choices: Schema.Array(Schema.Struct({ value: ChoiceValue, description: Schema.optional(Schema.String) })),
});
export const ScoreQuestion = Schema.Struct({
    name: Schema.String,
    type: Schema.Literal("score"),
    instructions: Schema.String,
    levels: Schema.Array(Schema.Struct({ label: Schema.String, description: Schema.optional(Schema.String) })),
});
export const DecisionQuestion = Schema.Union([PredicateQuestion, ChoiceQuestion, ScoreQuestion]).pipe(Schema.toTaggedUnion("type"));
// Only what makes a request meaningless is checked here; counts and sizes are the host's to enforce.
const DecisionQuestionList = Schema.Array(DecisionQuestion).pipe(Schema.refine((x) => x.length > 0, { message: "Decision questions must not be empty" }), Schema.refine((x) => new Set(x.map((question) => question.name)).size === x.length, {
    message: "Decision question names must be unique",
}));
// ---------------------------------------------------------------------------
// Answers
// ---------------------------------------------------------------------------
const Probability = Schema.Number.check(Schema.isBetween({ minimum: 0, maximum: 1 }));
export const PredicateAnswer = Schema.Struct({
    name: Schema.String,
    type: Schema.Literal("predicate"),
    probability: Probability,
});
export const ChoiceAnswer = Schema.Struct({
    name: Schema.String,
    type: Schema.Literal("choice"),
    choice: ChoiceValue,
    probabilities: Schema.Array(Schema.Struct({ value: ChoiceValue, probability: Probability })),
    confidence: Probability,
});
/** `score` is the probability-weighted level index; `probabilities` has one entry per level. */
export const ScoreAnswer = Schema.Struct({
    name: Schema.String,
    type: Schema.Literal("score"),
    score: Schema.Number,
    probabilities: Schema.Array(Schema.Struct({ value: Schema.Int, label: Schema.String, probability: Probability })),
    confidence: Probability,
});
export const ErrorReason = Schema.Union([Schema.Literal("refusal"), Schema.String]);
/** This one question has no answer; the other answers still came back. */
export const ErrorAnswer = Schema.Struct({
    name: Schema.String,
    type: Schema.Literal("error"),
    reason: ErrorReason,
    message: Schema.optional(Schema.String),
});
export const DecisionAnswer = Schema.Union([PredicateAnswer, ChoiceAnswer, ScoreAnswer, ErrorAnswer]).pipe(Schema.toTaggedUnion("type"));
/** Host quirks a protocol adapts to, like `LanguageModelCompatibility` for language models. */
export class DecisionModelCompatibility extends Schema.Class("Decision.ModelCompatibility")({
    /**
     * Where a System One host reads media, from models.dev `[api.systemone] compatibility.media_input`, named after
     * where the media goes in the body: `assets` (TypeSafe's assets map, referenced from the state), `state` (items
     * inside a state list) or `root` (one top-level list per kind: `images`, `audio`, `videos`).
     */
    mediaInput: Schema.optional(Schema.Literals(["assets", "state", "root"])),
}) {
}
(function (DecisionModelCompatibility) {
    DecisionModelCompatibility.make = (input) => input instanceof DecisionModelCompatibility ? input : new DecisionModelCompatibility(input);
})(DecisionModelCompatibility || (DecisionModelCompatibility = {}));
export class DecisionModel {
    id;
    provider;
    route;
    http;
    compatibility;
    /** Defaults under each request's `providerOptions`, such as options a provider package reads from its settings. */
    providerOptions;
    constructor(input) {
        this.id = input.id;
        this.provider = input.provider;
        this.route = input.route;
        this.http = input.http;
        this.compatibility = input.compatibility;
        this.providerOptions = input.providerOptions;
    }
    static make(input) {
        return new DecisionModel({
            ...input,
            id: ModelID.make(input.id),
            provider: ProviderID.make(input.provider),
        });
    }
}
export const DecisionModelSchema = Schema.declare((value) => value instanceof DecisionModel, {
    expected: "Decision.Model",
});
// ---------------------------------------------------------------------------
// Request and response
// ---------------------------------------------------------------------------
export class DecisionRequest extends Schema.Class("Decision.Request")({
    model: DecisionModelSchema,
    input: Schema.Array(DecisionPart),
    questions: DecisionQuestionList,
    providerOptions: Schema.optional(ProviderOptions),
    http: Schema.optional(HttpOptions),
}) {
}
/** What decision hosts report; their raw usage stays in the response's `providerMetadata`. */
export class DecisionUsage extends Schema.Class("Decision.Usage")({
    inputTokens: Schema.optional(Schema.Number),
    outputTokens: Schema.optional(Schema.Number),
    totalTokens: Schema.optional(Schema.Number),
    /** USD the host says it charged for this request. */
    cost: Schema.optional(Schema.Number),
}) {
}
export class DecisionResponse extends Schema.Class("Decision.Response")({
    answers: Schema.Array(DecisionAnswer),
    usage: Schema.optional(DecisionUsage),
    providerMetadata: Schema.optional(ProviderMetadata),
}) {
}
export function request(input) {
    if (input instanceof DecisionRequest)
        return input;
    return new DecisionRequest({
        ...input,
        input: Array.isArray(input.input) ? input.input : [{ type: "json", value: input.input }],
        http: HttpOptions.make(input.http),
    });
}
export function generate(input) {
    return tryRequest(() => request(input)).pipe(Effect.flatMap(DecisionClient.generate));
}
export const Decision = {
    request,
    generate,
};
